import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷三·25","description":"易小帖 - 卷三·25","frontmatter":{"title":"卷三·25","description":"易小帖 - 卷三·25"},"headers":[],"relativePath":"zh/classics/yixiaotie/093.md","filePath":"zh/classics/yixiaotie/093.md"}'),o={name:"zh/classics/yixiaotie/093.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷三·25",tabindex:"-1"},[r("卷三·25 "),e("a",{class:"header-anchor",href:"#卷三·25","aria-label":"Permalink to “卷三·25”"},"​")],-1),e("p",null,"艮為門闕，故凡言門者必有艮象在其中。惟同人初九「同人於門」本卦無艮，不知同人從姤來，姤初移二，則初與二皆陰爻，連三為艮為門，此推易法也。虞仲翔謂「乾為門」，此本《大傳》「乾坤其易之門耶」語。然同人五爻皆乾，而以初同於四為出門，則於象有未安矣。若乾為門，不補入《說卦》者，以《大傳》已有易之門語，則不必補耳。他倣此。",-1)])])}const h=t(o,[["render",c]]);export{f as __pageData,h as default};
